// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBarlow = makeLoadFont('BarlowCondensed');
const loadInter = makeLoadFont('Inter');

// Load clean geometric and condensed fonts at module level
const { fontFamily: barlowFamily } = loadBarlow();
const { fontFamily: interFamily } = loadInter();



export type IncomeHighlightProps = Record<string, any>;

const DotGrid: React.FC<{ color: string; opacity: number }> = ({ color, opacity }) => {
  const dots = [];
  for (let i = 0; i < 6; i++) {
    const row = [];
    for (let j = 0; j < 5; j++) {
      row.push(
        <div
          key={j}
          style={{
            width: 4,
            height: 4,
            borderRadius: "50%",
            backgroundColor: color,
            margin: 5,
            opacity: 0.4,
            transition: "none",
          }}
        />
      );
    }
    dots.push(
      <div key={i} style={{ display: "flex", flexDirection: "column", transition: "none" }}>
        {row}
      </div>
    );
  }

  return (
    <div
      style={{
        position: "absolute",
        right: "6%",
        bottom: "22%",
        opacity,
        display: "flex",
        flexDirection: "row",
        transition: "none",
      }}
    >
      {dots}
    </div>
  );
};

const IncomeHighlight: React.FC<IncomeHighlightProps> = ({
  backgroundColor = "#0c1015",
  primaryColor = "#1df2a5",
  textColor = "#ffffff",
  subtitle = "A QUALIFYING INCOME OF",
  amount = 200000,
  currencySymbol = "$",
  transparentBackground = false,
  durationInSeconds = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safely resolve background color
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // SKEW angle matches the visual mockup (~18 degrees)
  const skewAngle = -18;

  // 1. Box Scale & Opacity Animation (Spring loaded)
  const boxSpring = spring({
    frame: frame - 8,
    fps,
    config: { damping: 15, stiffness: 80, mass: 1 },
  });
  const boxScale = interpolate(boxSpring, [0, 1], [0.85, 1]);
  const boxOpacity = interpolate(boxSpring, [0, 1], [0, 1]);

  // 2. Slanted Backdrop Band Slide In
  const bandSpring = spring({
    frame: frame - 2,
    fps,
    config: { damping: 18, stiffness: 60 },
  });
  const bandTranslateX = interpolate(bandSpring, [0, 1], [250, 0]);
  const bandOpacity = interpolate(bandSpring, [0, 1], [0, 1]);

  // 3. Diagonal Accent Lines Transition (Draw length & slide)
  const linesSpring = spring({
    frame: frame - 18,
    fps,
    config: { damping: 14, stiffness: 70 },
  });
  const lineProgress = interpolate(linesSpring, [0, 1], [0, 1]);
  const lineOpacity = interpolate(linesSpring, [0, 1], [0, 1]);

  // 4. Subtitle Text Fade In & Slide down
  const subtitleOpacity = interpolate(frame, [22, 42], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const subtitleTranslateY = interpolate(frame, [22, 42], [-15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 5. Main Number Count Up Easing (Smooth ease-out exponent)
  const countProgress = interpolate(frame, [25, 75], [0, 1], {
    easing: Easing.bezier(0.16, 1, 0.3, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const currentAmountValue = interpolate(countProgress, [0, 1], [0, amount]);
  const formattedAmount = Math.floor(currentAmountValue).toLocaleString("en-US");

  // Number scale and opacity reveal
  const numberSpring = spring({
    frame: frame - 24,
    fps,
    config: { damping: 15, stiffness: 90 },
  });
  const numberScale = interpolate(numberSpring, [0, 1], [0.92, 1]);
  const numberOpacity = interpolate(numberSpring, [0, 1], [0, 1]);

  // Glow pulse once the animation finishes
  const glowOpacity = interpolate(frame, [65, 85], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Dot Grid Reveal
  const dotOpacity = interpolate(frame, [35, 60], [0, 0.25], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Gentle Idle Hover Effect (Only active once the intro settles)
  const idleMultiplier = interpolate(frame, [60, 90], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const idleY = Math.sin(frame * 0.05) * 6 * idleMultiplier;
  const idleX = Math.cos(frame * 0.03) * 3 * idleMultiplier;

  // Responsive Layout Calculations
  const boxWidth = width * 0.65;
  const boxHeight = height * 0.44;
  const centerX = width * 0.44; // Placed slightly to the left to match original occupancy
  const centerY = height * 0.52;

  const boxLeft = centerX - boxWidth / 2;
  const boxTop = centerY - boxHeight / 2;

  // Auto-shrink font size if amount is exceptionally long to prevent bounding box issues
  const rawStringLength = formattedAmount.length + currencySymbol.length;
  const fontShrinkFactor = Math.min(1, 10 / rawStringLength);
  const amountFontSize = width * 0.12 * fontShrinkFactor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", transition: "none" }}>
      {/* Background Visual Structure */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(circle at 30% 30%, ${backgroundColor} 0%, #05070a 100%)`,
          transition: "none",
        }}
      />

      {/* Slanted Backdrop Band (Right Side) */}
      <div
        style={{
          position: "absolute",
          width: width * 0.32,
          height: height * 1.6,
          top: -height * 0.3,
          right: width * 0.02,
          background: `linear-gradient(135deg, ${primaryColor}2a 0%, ${primaryColor}03 70%)`,
          borderLeft: `2.5px solid ${primaryColor}3a`,
          transform: `skewX(${skewAngle}deg) translateX(${bandTranslateX}px)`,
          opacity: bandOpacity,
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Decorative Dot Grid */}
      <DotGrid color={primaryColor} opacity={dotOpacity} />

      {/* Main Slanted Accent Lines */}
      {/* Top Right Line */}
      <div
        style={{
          position: "absolute",
          width: 2,
          height: height * 0.38,
          backgroundColor: textColor,
          left: boxLeft + boxWidth + width * 0.015,
          top: boxTop - height * 0.22,
          transform: `skewX(${skewAngle}deg) scaleY(${lineProgress}) translateY(${(1 - lineProgress) * -100}px)`,
          transformOrigin: "bottom",
          opacity: lineOpacity * 0.9,
          transition: "none",
        }}
      />

      {/* Bottom Left Line */}
      <div
        style={{
          position: "absolute",
          width: 2,
          height: height * 0.38,
          backgroundColor: textColor,
          left: boxLeft - width * 0.05,
          top: boxTop + boxHeight - height * 0.16,
          transform: `skewX(${skewAngle}deg) scaleY(${lineProgress}) translateY(${(1 - lineProgress) * 100}px)`,
          transformOrigin: "top",
          opacity: lineOpacity * 0.9,
          transition: "none",
        }}
      />

      {/* Primary Slanted Container Box */}
      <div
        style={{
          position: "absolute",
          width: boxWidth,
          height: boxHeight,
          left: boxLeft,
          top: boxTop,
          border: `1.5px solid ${primaryColor}88`,
          transform: `skewX(${skewAngle}deg) scale(${boxScale}) translate(${idleX}px, ${idleY}px)`,
          opacity: boxOpacity,
          display: "flex",
          alignItems: "center",
          justifyContent: "flex-start",
          paddingLeft: width * 0.065,
          boxSizing: "border-box",
          transition: "none",
        }}
      >
        {/* Un-skewed inner content wrapper */}
        <div
          style={{
            transform: `skewX(${-skewAngle}deg)`,
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            width: "100%",
            transition: "none",
          }}
        >
          {/* Subtitle */}
          <div
            style={{
              fontFamily: interFamily,
              color: textColor,
              fontSize: width * 0.021,
              fontWeight: 700,
              letterSpacing: "0.15em",
              textTransform: "uppercase",
              opacity: subtitleOpacity,
              transform: `translateY(${subtitleTranslateY}px)`,
              marginBottom: height * 0.005,
              transition: "none",
            }}
          >
            {subtitle}
          </div>

          {/* Amount Showcase */}
          <div
            style={{
              display: "flex",
              alignItems: "flex-start",
              color: primaryColor,
              fontFamily: barlowFamily,
              fontWeight: 800,
              opacity: numberOpacity,
              transform: `scale(${numberScale})`,
              filter: `drop-shadow(0 0 ${25 * glowOpacity}px ${primaryColor}55)`,
              transition: "none",
            }}
          >
            {/* Currency Prefix */}
            <span
              style={{
                fontSize: amountFontSize * 0.58,
                marginTop: amountFontSize * 0.11,
                marginRight: width * 0.006,
                fontWeight: 700,
                lineHeight: 1,
                transition: "none",
              }}
            >
              {currencySymbol}
            </span>

            {/* Target Value Counter */}
            <span
              style={{
                fontSize: amountFontSize,
                lineHeight: 0.88,
                letterSpacing: "-0.01em",
                transition: "none",
              }}
            >
              {formattedAmount}
            </span>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default IncomeHighlight;